// pastedCallback is a sample of the real callback URL stranded on 127.0.0.1 after browser authorization.
//
// It is the key evidence for the entire bug: both the outer secret and the ticket_id / secret in redirect are
// **issued by Huawei Cloud**, not the pair sent into /authorize by LoginStart. Previously, the plugin always polled
// with self-generated values, so the console was stuck forever at "Waiting for authorization...".
const pastedCallback = "http://127.0.0.1/oauth/callback?secret=d55df9259e688e2a71b93f058c748349782ca1a30440473980961ef6833ee280" +
	"&redirect=https%3A%2F%2Fcodearts.huaweicloud.com%2Fportal%2Flogin%3Ftheme%3Dlight%26locale%3Dzh-cn" +
	"%26ticket_id%3D657abbb247eab363d1a461285fc50145%26authorizationAvailable%3Dfalse" +
	"%26secret%3Dd55df9259e688e2a71b93f058c748349782ca1a30440473980961ef6833ee280"

const (
	upstreamTicketID = "657abbb247eab363d1a461285fc50145"
	upstreamSecret   = "d55df9259e688e2a71b93f058c748349782ca1a30440473980961ef6833ee280"
)

// useLoopbackHost hooks the host's host.http.do onto the real http.Client.
//
// Outbound requests always go through the host bridge (proxies, auditing, and metrics are attached to that link), so if a unit test
// wants to verify "whether the outgoing query parameters are correct", it must first set up this bridge—otherwise requests cannot even be sent out.
func useLoopbackHost(t *testing.T) {
	t.Helper()
	hostbridge.Configure(func(callbackID, method string, payload any) (json.RawMessage, error) {
		if method != pluginabi.MethodHostHTTPDo {
			return nil, nil
		}
		rawPayload, errMarshal := json.Marshal(payload)
		if errMarshal != nil {
			return nil, errMarshal
		}
		var req struct {
			Method  string              `json:"method"`
			URL     string              `json:"url"`
			Headers map[string][]string `json:"headers"`
			Body    []byte              `json:"body"`
		}
		if errDecode := json.Unmarshal(rawPayload, &req); errDecode != nil {
			return nil, errDecode
		}
		var bodyReader io.Reader
		if len(req.Body) > 0 {
			bodyReader = strings.NewReader(string(req.Body))
		}
		httpReq, errNew := http.NewRequest(req.Method, req.URL, bodyReader)
		if errNew != nil {
			return nil, errNew
		}
		for key, values := range req.Headers {
			for _, value := range values {
				httpReq.Header.Add(key, value)
			}
		}
		resp, errDo := (&http.Client{Timeout: 10 * time.Second}).Do(httpReq)
		if errDo != nil {
			return nil, errDo
		}
		defer func() { _ = resp.Body.Close() }()
		respBody, errRead := io.ReadAll(resp.Body)
		if errRead != nil {
			return nil, errRead
		}
		return json.Marshal(map[string]any{"StatusCode": resp.StatusCode, "Headers": resp.Header, "Body": respBody})
	})
	t.Cleanup(func() { hostbridge.Configure(nil) })
}

// TestParseCallbackTakesUpstreamTicket locks down the parsing criteria: ticket_id / secret are taken from the callback
// (including the portal login address inside redirect), rather than the pair self-generated by the plugin.
func TestParseCallbackTakesUpstreamTicket(t *testing.T) {
	info, errParse := ParseCallback(pastedCallback)
	if errParse != nil {
		t.Fatalf("parse callback: %v", errParse)
	}
	if info.TicketID != upstreamTicketID {
		t.Fatalf("ticket id = %q, want %q", info.TicketID, upstreamTicketID)
	}
	if info.Secret != upstreamSecret {
		t.Fatalf("secret = %q, want %q", info.Secret, upstreamSecret)
	}
	if info.Redirect == "" {
		t.Fatal("redirect not preserved: user still needs it to continue authorization when ticket is not exchanged for credential")
	}
}

// TestParseCallbackRejectsLinkWithoutTicket guards the lower bound of parsing: links without a ticket cannot be
// treated as valid callbacks (otherwise the user will only see an inexplicable upstream error).
func TestParseCallbackRejectsLinkWithoutTicket(t *testing.T) {
	if _, errParse := ParseCallback("http://127.0.0.1/oauth/callback?secret=only-secret"); errParse == nil {
		t.Fatal("links with only secret and no code/redirect must fail to parse")
	}
}

// TestSubmitCallbackKeepsSessionTicket locks down the most error-prone point of the ticket channel:
//
// that ticket_id in the callback is the portal's intermediate ticket; using it to query the ticket API will inevitably result in "invalid ticketId"
// (observed TM.00001001). The only thing that truly needs to be exchanged is the secret—the ticket_id must remain this session's own.
func TestSubmitCallbackKeepsSessionTicket(t *testing.T) {
	useLoopbackHost(t)
	var gotTicket, gotSecret string
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		gotTicket = r.URL.Query().Get("ticket_id")
		gotSecret = r.URL.Query().Get("secret")
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"user_id":"user-1","user_name":"tester","refresh_token":"refresh-1",` +
			`"credentials":{"access_key_id":"AK-test","secret_access_key":"SK-test",` +
			`"security_token":"ST-test","expiration":"2026-10-19T18:00:00Z"}}`))
	}))
	defer server.Close()

	// The session's ticket number must match the one in the callback redirect, so we take the one in the callback as the session ticket number here.
	info, errParse := ParseCallback(pastedCallback)
	if errParse != nil {
		t.Fatalf("parse callback: %v", errParse)
	}
	logins := auth.NewSessionRegistry()
	logins.Register(VendorID, "codearts_paste", 15*time.Minute, 0, &pendingLogin{
		TicketID:  info.TicketID,
		Secret:    "self-made-secret",
		TicketURL: server.URL,
	})

	result, errSubmit := SubmitCallback(context.Background(), logins, "codearts_paste", pastedCallback)
	if errSubmit != nil {
		t.Fatalf("submit callback: %v", errSubmit)
	}
	if result.Status != pluginapi.AuthLoginStatusSuccess {
		t.Fatalf("status = %q, want success (message=%q)", result.Status, result.Message)
	}
	if gotTicket != info.TicketID {
		t.Fatalf("ticket query used %q, want session's %q (cannot be replaced with portal's intermediate ticket)", gotTicket, info.TicketID)
	}
	if gotSecret != upstreamSecret {
		t.Fatalf("ticket query used secret %q, want portal-issued %q", gotSecret, upstreamSecret)
	}
	if result.Auth.FileName != "codearts-user-1.json" {
		t.Fatalf("file name = %q, want codearts-user-1.json", result.Auth.FileName)
	}

	var storage map[string]any
	if err := json.Unmarshal(result.Auth.StorageJSON, &storage); err != nil {
		t.Fatalf("decode storage json: %v", err)
	}
	if storage["access_key_id"] != "AK-test" {
		t.Fatalf("credential not persisted: %v", storage["access_key_id"])
	}
}

// TestSubmitCallbackRejectsForeignTicket guards ownership: when the ticket number in the callback does not match the session,
// the session state cannot be modified, otherwise a single mispaste could write credentials into someone else's login session.
func TestSubmitCallbackRejectsForeignTicket(t *testing.T) {
	logins := auth.NewSessionRegistry()
	logins.Register(VendorID, "codearts_foreign", 15*time.Minute, 0, &pendingLogin{
		TicketID: "00000000000000000000000000000000",
		Secret:   "self-made-secret",
	})

	_, errSubmit := SubmitCallback(context.Background(), logins, "codearts_foreign", pastedCallback)
	if errSubmit == nil {
		t.Fatal("must error out when ticket number does not belong to this session")
	}
}

// TestSubmitCallbackKeepsPortalURLWhilePending locks down the "credential not yet exchanged" step: carrying back the portal login address
// from the callback so the user can continue completing authorization in a connected browser, while the plugin continues polling.
func TestSubmitCallbackKeepsPortalURLWhilePending(t *testing.T) {
	useLoopbackHost(t)
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusForbidden)
	}))
	defer server.Close()

	logins := auth.NewSessionRegistry()
	logins.Register(VendorID, "codearts_pending", 15*time.Minute, 0, &pendingLogin{TicketURL: server.URL})

	result, errSubmit := SubmitCallback(context.Background(), logins, "codearts_pending", pastedCallback)
	if errSubmit != nil {
		t.Fatalf("submit callback: %v", errSubmit)
	}
	if result.Status != pluginapi.AuthLoginStatusPending {
		t.Fatalf("status = %q, want pending", result.Status)
	}
	if result.RedirectURL == "" {
		t.Fatal("portal login address must be returned on pending, otherwise user has no next step")
	}
}

// TestSubmitCallbackRejectsUnknownSession guards session boundaries: credentials cannot be exchanged based on a single link
// when there is no login session.
func TestSubmitCallbackRejectsUnknownSession(t *testing.T) {
	if _, errSubmit := SubmitCallback(context.Background(), auth.NewSessionRegistry(), "codearts_missing", pastedCallback); errSubmit == nil {
		t.Fatal("unknown session must return an error")
	}
}

// TestSubmitCallbackKeepsWaitingOnInvalidTicket locks down a counter-intuitive but necessary behavior:
//
// Upstream returns the exact same TM.00001001 invalid ticketId for both "ticket not yet active" and "ticket number does not exist"
// (observed: making up a ticket_id yields this exact message). Therefore, this message **cannot** be treated as a terminal state—judging it as a failure
// would permanently nail "user hasn't finished clicking authorization" as "ticket has expired, please re-initiate login".
func TestSubmitCallbackKeepsWaitingOnInvalidTicket(t *testing.T) {
	useLoopbackHost(t)
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusBadRequest)
		_, _ = w.Write([]byte(`{"error_code":"TM.00001001","error_msg":"无效ticketId: ` + upstreamTicketID + `"}`))
	}))
	defer server.Close()

	info, errParse := ParseCallback(pastedCallback)
	if errParse != nil {
		t.Fatalf("parse callback: %v", errParse)
	}
	logins := auth.NewSessionRegistry()
	logins.Register(VendorID, "codearts_wait", 15*time.Minute, 0, &pendingLogin{
		TicketID: info.TicketID, TicketURL: server.URL,
	})

	result, errSubmit := SubmitCallback(context.Background(), logins, "codearts_wait", pastedCallback)
	if errSubmit != nil {
		t.Fatalf("inactive ticket is considered waiting, should not error: %v", errSubmit)
	}
	if result.Status != pluginapi.AuthLoginStatusPending {
		t.Fatalf("status = %q, want pending", result.Status)
	}
	if !strings.Contains(result.Message, "TM.00001001") {
		t.Fatalf("waiting prompt lacks upstream reason: %q", result.Message)
	}
	if result.RedirectURL == "" {
		t.Fatal("portal login page must be returned when waiting, otherwise user has no next step")
	}
}

// TestSubmitCallbackSurfacesUpstreamNote locks down diagnostic message passthrough: while still waiting, the page must
// be able to see what upstream actually said, otherwise "waiting" can neither be self-inspected nor reported.
func TestSubmitCallbackSurfacesUpstreamNote(t *testing.T) {
	useLoopbackHost(t)
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusForbidden)
		_, _ = w.Write([]byte(`{"error_code":"TM.00001002","error_msg":"用户尚未完成授权"}`))
	}))
	defer server.Close()

	logins := auth.NewSessionRegistry()
	info, errParse := ParseCallback(pastedCallback)
	if errParse != nil {
		t.Fatalf("parse callback: %v", errParse)
	}
	logins.Register(VendorID, "codearts_waiting", 15*time.Minute, 0,
		&pendingLogin{TicketID: info.TicketID, TicketURL: server.URL})

	result, errSubmit := SubmitCallback(context.Background(), logins, "codearts_waiting", pastedCallback)
	if errSubmit != nil {
		t.Fatalf("unauthorized is considered waiting, should not error: %v", errSubmit)
	}
	if result.Status != pluginapi.AuthLoginStatusPending {
		t.Fatalf("status = %q, want pending", result.Status)
	}
	if !strings.Contains(result.Message, "TM.00001002") {
		t.Fatalf("pending prompt lacks upstream reason: %q", result.Message)
	}
	if result.RedirectURL == "" {
		t.Fatal("portal login address still required when pending")
	}
}
